mapper.select:
SELECT * FROM ( SELECT i.id, i.user_id, i.target_type, i.target_id, i.type, i.create_time, p.project_name AS targetTitle, p.cover_url AS targetCover FROM interaction i JOIN ich_project p ON p.id = i.target_id AND p.deleted = 0 AND p.audit_status = 1 WHERE i.deleted = 0 AND i.type = 1 AND i.target_type = 1 AND i.user_id = #{userId}
UNION ALL
SELECT i.id, i.user_id, i.target_type, i.target_id, i.type, i.create_time, a.title AS targetTitle, a.cover_url AS targetCover FROM interaction i JOIN cms_article a ON a.id = i.target_id AND a.deleted = 0 AND a.audit_status = 1 WHERE i.deleted = 0 AND i.type = 1 AND i.target_type = 2 AND i.user_id = #{userId}
UNION ALL
SELECT i.id, i.user_id, i.target_type, i.target_id, i.type, i.create_time, ac.title AS targetTitle, ac.cover_url AS targetCover FROM interaction i JOIN ich_activity ac ON ac.id = i.target_id AND ac.deleted = 0 AND ac.status >= 1 WHERE i.deleted = 0 AND i.type = 1 AND i.target_type = 3 AND i.user_id = #{userId} ) t ORDER BY t.create_time DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT i.id FROM interaction i
    JOIN ich_project p ON p.id = i.target_id AND p.deleted = 0 AND p.audit_status = 1
    WHERE i.deleted = 0 AND i.type = 1 AND i.target_type = 1 AND i.user_id = #{userId}
    UNION ALL
    SELECT i.id FROM interaction i
    JOIN cms_article a ON a.id = i.target_id AND a.deleted = 0 AND a.audit_status = 1
    WHERE i.deleted = 0 AND i.type = 1 AND i.target_type = 2 AND i.user_id = #{userId}
    UNION ALL
    SELECT i.id FROM interaction i
    JOIN ich_activity ac ON ac.id = i.target_id AND ac.deleted = 0 AND ac.status >= 1
    WHERE i.deleted = 0 AND i.type = 1 AND i.target_type = 3 AND i.user_id = #{userId}
) t
